"use strict";var Logout=function(n){var t={initialize:function(){t.initEvent()},initEvent:function(){n("#btnLogout").on("click",function(){t.handleShowFeedback()});n("#btnLogoutMobile").on("click",function(){t.handleShowFeedback()})},handleShowFeedback:function(){n.ajax({url:Site.resolveRelativeUrl("UserPanel/Feedback/Index?isClickLogout=true"),type:"GET",dataType:"html",cache:!1,success:function(t){n("#btnMyAccount").append('<div id="affFeedback">'+t+"<\/div>")},complete:function(){n("#affFeedbackContainer").length||(n("#affFeedback").remove(),window.location.href=Site.resolveRelativeUrl("Auth/SignOut"))}})}};return t}(jQuery);Logout.initialize();